import { useRef, useState } from 'react';
import { BellIcon, MagnifyingGlassIcon } from '@phosphor-icons/react';
import { ActionIcon, AppShell, Burger, Group, Stack, Text, TextInput, Title } from '@mantine/core';
import { useDisclosure } from '@mantine/hooks';
import { MantineLogo } from '@mantinex/mantine-logo';
import { Order } from './data';
import { Navbar } from './Navbar';
import { OrderDetails } from './OrderDetails';
import { OrdersTable } from './OrdersTable';
import { UserMenu } from './UserMenu';
import classes from './AsideDetails.module.css';

export function AsideDetails() {
  const [opened, { toggle }] = useDisclosure();
  const [selected, setSelected] = useState<Order | null>(null);
  const orderControlsRef = useRef<Record<string, HTMLButtonElement | null>>({});

  const handleClose = () => {
    if (selected) {
      orderControlsRef.current[selected.id]?.focus();
    }
    setSelected(null);
  };

  return (
    <AppShell
      header={{ height: 60 }}
      navbar={{ width: 260, breakpoint: 'sm', collapsed: { mobile: !opened } }}
      aside={{ width: 320, breakpoint: 'sm', collapsed: { desktop: !selected, mobile: !selected } }}
      padding={{ base: 'md', sm: 'xl' }}
    >
      <AppShell.Header>
        <Group h="100%" px="md" justify="space-between">
          <Group>
            <Burger
              opened={opened}
              onClick={toggle}
              hiddenFrom="sm"
              size="sm"
              aria-label="Toggle navigation"
            />
            <MantineLogo size={28} />
          </Group>

          <Group>
            <TextInput
              placeholder="Search"
              leftSection={<MagnifyingGlassIcon size={16} />}
              visibleFrom="sm"
              w={240}
            />
            <ActionIcon
              variant="default"
              size="lg"
              aria-label="Notifications"
              title="Notifications"
            >
              <BellIcon size={18} />
            </ActionIcon>
            <UserMenu />
          </Group>
        </Group>
      </AppShell.Header>

      <AppShell.Navbar>
        <Navbar />
      </AppShell.Navbar>

      <AppShell.Main className={classes.main}>
        <Stack gap="lg">
          <div>
            <Title order={2} c="var(--mantine-color-bright)">
              Orders
            </Title>
            <Text size="sm">Select an order to see its details</Text>
          </div>
          <OrdersTable
            selected={selected}
            onSelect={setSelected}
            orderControlsRef={orderControlsRef}
          />
        </Stack>
      </AppShell.Main>

      <AppShell.Aside p="md">
        {selected && <OrderDetails order={selected} onClose={handleClose} />}
      </AppShell.Aside>
    </AppShell>
  );
}

import { useState } from 'react';
import { AppShell, Badge, NavLink, ScrollArea } from '@mantine/core';
import { footerLinks, mainLinks } from './data';

export function Navbar() {
  const [active, setActive] = useState('Dashboard');

  const renderLinks = (links: typeof mainLinks) =>
    links.map((link) => (
      <NavLink
        key={link.label}
        href="#"
        variant="rail"
        label={link.label}
        leftSection={<link.icon size={18} />}
        rightSection={link.badge && <Badge variant="default">{link.badge}</Badge>}
        active={link.label === active}
        onClick={(event) => {
          event.preventDefault();
          setActive(link.label);
        }}
      />
    ));

  return (
    <>
      <AppShell.Section grow component={ScrollArea} p="md">
        {renderLinks(mainLinks)}
      </AppShell.Section>
      <AppShell.Section p="md">{renderLinks(footerLinks)}</AppShell.Section>
    </>
  );
}

import { useEffect, useRef } from 'react';
import { XIcon } from '@phosphor-icons/react';
import { ActionIcon, Badge, Button, Group, Stack, Text, Title } from '@mantine/core';
import { Order, statusColors } from './data';

interface OrderDetailsProps {
  order: Order;
  onClose: () => void;
}

export function OrderDetails({ order, onClose }: OrderDetailsProps) {
  const closeButton = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    closeButton.current?.focus();
  }, []);

  const email = `${order.customer.toLowerCase().replace(' ', '.')}@example.com`;

  const fields = [
    ['Customer', order.customer],
    ['Email', email],
    ['Date', order.date],
    ['Amount', order.amount],
  ].map(([label, value]) => (
    <Group key={label} justify="space-between" wrap="nowrap">
      <Text size="sm">{label}</Text>
      <Text size="sm" fw={500} ta="right">
        {value}
      </Text>
    </Group>
  ));

  return (
    <Stack gap="md">
      <Group justify="space-between" wrap="nowrap">
        <Title order={3} fz="md" c="var(--mantine-color-bright)">
          Order {order.id}
        </Title>
        <ActionIcon
          ref={closeButton}
          variant="default"
          aria-label="Close details"
          title="Close"
          onClick={onClose}
        >
          <XIcon size={16} />
        </ActionIcon>
      </Group>

      <Badge color={statusColors[order.status]}>{order.status}</Badge>

      <Stack gap="xs">{fields}</Stack>

      <Group justify="flex-end" mt="md">
        <Button variant="default">Refund</Button>
        <Button>Send invoice</Button>
      </Group>
    </Stack>
  );
}

import { RefObject } from 'react';
import { Badge, Surface, Table, Title, UnstyledButton } from '@mantine/core';
import { Order, orders, statusColors } from './data';
import classes from './OrdersTable.module.css';

interface OrdersTableProps {
  selected: Order | null;
  onSelect: (order: Order) => void;
  orderControlsRef: RefObject<Record<string, HTMLButtonElement | null>>;
}

export function OrdersTable({ selected, onSelect, orderControlsRef }: OrdersTableProps) {
  const rows = orders.map((order) => (
    <Table.Tr
      key={order.id}
      className={classes.row}
      data-selected={order.id === selected?.id || undefined}
      onClick={() => onSelect(order)}
    >
      <Table.Td>
        <UnstyledButton
          ref={(node) => {
            orderControlsRef.current[order.id] = node;
          }}
          fz="inherit"
        >
          {order.id}
        </UnstyledButton>
      </Table.Td>
      <Table.Td>{order.customer}</Table.Td>
      <Table.Td>{order.date}</Table.Td>
      <Table.Td>
        <Badge color={statusColors[order.status]}>{order.status}</Badge>
      </Table.Td>
      <Table.Td ta="right">{order.amount}</Table.Td>
    </Table.Tr>
  ));

  return (
    <Surface level={0} withBorder>
      <Title order={3} fz="md" p="md" c="var(--mantine-color-bright)">
        Recent orders
      </Title>
      <Table.ScrollContainer minWidth={500}>
        <Table verticalSpacing="sm" horizontalSpacing="md" highlightOnHover>
          <Table.Thead>
            <Table.Tr>
              <Table.Th>Order</Table.Th>
              <Table.Th>Customer</Table.Th>
              <Table.Th>Date</Table.Th>
              <Table.Th>Status</Table.Th>
              <Table.Th ta="right">Amount</Table.Th>
            </Table.Tr>
          </Table.Thead>
          <Table.Tbody>{rows}</Table.Tbody>
        </Table>
      </Table.ScrollContainer>
    </Surface>
  );
}

